// Minimal Asteroid Dash game
// Canvas with id "game" must exist in the HTML.
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas #game not found');
  const ctx = canvas.getContext('2d');
  const W = (canvas.width = canvas.clientWidth || 800);
  const H = (canvas.height = canvas.clientHeight || 600);

  // Ship definition
  const ship = {
    x: W / 2,
    y: H / 2,
    r: 12,
    angle: 0,
    speed: 0,
    maxSpeed: 3,
    thrust: 0.1,
    fuel: 100,
    fuelDrain: 0.02,
  };

  const keys = {};
  addEventListener('keydown', e => (keys[e.key] = true));
  addEventListener('keyup', e => (keys[e.key] = false));

  // Asteroid pool
  const asteroids = [];
  function spawnAsteroid() {
    const radius = 15 + Math.random() * 20;
    const side = Math.random() < 0.5 ? 'left' : 'right';
    const x = side === 'left' ? -radius : W + radius;
    const y = Math.random() * H;
    const speed = 1 + Math.random() * 2;
    const angle = side === 'left' ? 0 : Math.PI;
    asteroids.push({ x, y, radius, speed, angle });
  }
  let spawnTimer = 0;

  // Simple starfield background
  const stars = Array.from({ length: 100 }, () => ({
    x: Math.random() * W,
    y: Math.random() * H,
    r: Math.random() * 1.5 + 0.5,
    speed: Math.random() * 0.5 + 0.2,
  }));

  function update() {
    // Controls
    if (keys['ArrowLeft']) ship.angle -= 0.05;
    if (keys['ArrowRight']) ship.angle += 0.05;
    if (keys['ArrowUp']) {
      ship.speed = Math.min(ship.maxSpeed, ship.speed + ship.thrust);
      ship.fuel = Math.max(0, ship.fuel - 0.1);
    } else {
      ship.speed *= 0.99; // drag
    }
    ship.x += Math.cos(ship.angle) * ship.speed;
    ship.y += Math.sin(ship.angle) * ship.speed;
    // wrap around
    if (ship.x < 0) ship.x += W;
    if (ship.x > W) ship.x -= W;
    if (ship.y < 0) ship.y += H;
    if (ship.y > H) ship.y -= H;
    ship.fuel = Math.max(0, ship.fuel - ship.fuelDrain);

    // Asteroids
    spawnTimer -= 1;
    if (spawnTimer <= 0) {
      spawnAsteroid();
      spawnTimer = 60 + Math.random() * 60; // approx 1‑2 sec
    }
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.x += Math.cos(a.angle) * a.speed;
      a.y += Math.sin(a.angle) * a.speed;
      // remove off‑screen
      if (a.x < -a.radius || a.x > W + a.radius) asteroids.splice(i, 1);
    }

    // Collision detection (circle)
    for (const a of asteroids) {
      const dx = a.x - ship.x;
      const dy = a.y - ship.y;
      const dist = Math.hypot(dx, dy);
      if (dist < a.radius + ship.r) {
        gameOver();
        return;
      }
    }
    if (ship.fuel <= 0) { gameOver(); return; }
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    // stars
    ctx.fillStyle = '#fff';
    for (const s of stars) {
      s.x += s.speed;
      if (s.x > W) s.x = 0;
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
      ctx.fill();
    }
    // ship
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.moveTo(ship.r, 0);
    ctx.lineTo(-ship.r, ship.r / 2);
    ctx.lineTo(-ship.r, -ship.r / 2);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
    // asteroids
    ctx.fillStyle = '#a52a2a';
    for (const a of asteroids) {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
      ctx.fill();
    }
    // fuel gauge
    ctx.fillStyle = '#555';
    ctx.fillRect(10, 10, 104, 14);
    ctx.fillStyle = '#ff0';
    ctx.fillRect(12, 12, ship.fuel, 10);
    ctx.strokeStyle = '#000';
    ctx.strokeRect(10, 10, 104, 14);
  }

  let running = true;
  function gameOver() {
    running = false;
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = '#fff';
    ctx.font = '24px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', W / 2, H / 2);
  }

  function loop() {
    if (!running) return;
    update();
    draw();
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
